function pdfBlob(jb,W,H){const e=new TextEncoder(),parts=[],off=[];let len=0;const add=d=>{const u=typeof d=='string'?e.encode(d):d;parts.push(u);len+=u.length},obj=(n,b)=>{off[n]=len;add(n+' 0 obj\n'+b+'\nendobj\n')},w=W/2,h=H/2;
  add('%PDF-1.4\n');obj(1,'<</Type/Catalog/Pages 2 0 R>>');obj(2,'<</Type/Pages/Kids[3 0 R]/Count 1>>');obj(3,`<</Type/Page/Parent 2 0 R/MediaBox[0 0 ${w} ${h}]/Resources<</XObject<</I 4 0 R>>>>/Contents 5 0 R>>`);
  off[4]=len;add(`4 0 obj\n<</Type/XObject/Subtype/Image/Width ${W}/Height ${H}/ColorSpace/DeviceRGB/BitsPerComponent 8/Filter/DCTDecode/Length ${jb.length}>>\nstream\n`);add(jb);add('\nendstream\nendobj\n');
  const c=`q ${w} 0 0 ${h} 0 0 cm /I Do Q`;obj(5,`<</Length ${c.length}>>\nstream\n${c}\nendstream`);const x=len;
  add('xref\n0 6\n0000000000 65535 f \n'+[1,2,3,4,5].map(n=>String(off[n]).padStart(10,'0')+' 00000 n \n').join('')+`trailer\n<</Size 6/Root 1 0 R>>\nstartxref\n${x}\n%%EOF`);return new Blob(parts,{type:'application/pdf'})}
async function rPdf(id,sh){const b=(await all('bills')).find(x=>x.id==id),c=bCanvas(b);c.toBlob(async jb=>{const pb=pdfBlob(new Uint8Array(await jb.arrayBuffer()),c.width,c.height),f=new File([pb],id+'.pdf',{type:'application/pdf'});
  if(sh&&navigator.canShare&&navigator.canShare({files:[f]})){try{await navigator.share({files:[f],title:'Bill '+id});return}catch(e){}}
  const a=document.createElement('a');a.href=URL.createObjectURL(pb);a.download=id+'.pdf';a.click();toast('PDF saved')},'image/jpeg',.92)}
let SC=null;const defSee=k=>SC?SC.includes(k):(k!='category'&&!String(k).startsWith('dt_')),canSee=k=>isA()||defSee(k),lb=l=>l=='Price'?'Salesman Price':l;
