function importV(){$('#app').innerHTML=`<p><button class="g" onclick="adminV('products')">← Product Management</button></p><h2>Import products</h2><div class="card"><b>Starter list: ${STARTER.length} products</b><p class="st">Paper, pens, markers, ink, scales, colours and more. Products already in your sheet are skipped, and you see the list of new ones before anything is added.</p><button onclick="doImport(STARTER)">📥 Import starter list</button></div><div class="card"><h3 style="margin-top:0">Paste more products</h3><p class="st">Paste a list like [{"cat":"Paper","name":"Local copy","sp":11,"cp":20}]. Needed: cat and name. sp = Price, cp = Counter Price.</p><textarea id="ij" rows="6" aria-label="Product list"></textarea><p><button onclick="pasteImport()">📥 Import pasted list</button></p></div>`}
async function pasteImport(){const t=$('#ij').value,a=t.indexOf('['),b=t.lastIndexOf(']');let L;try{L=JSON.parse(t.slice(a,b+1))}catch(e){return toast('Could not read the list. Paste it as [ {...}, {...} ]',1)}
  if(!Array.isArray(L)||!L.length)return toast('The list is empty',1);doImport(L)}
async function doImport(L,auto){await loadProducts();const k1=(CFG.prices.find(c=>c.key=='pr_price')||CFG.prices[0]||{}).key,k2=(CFG.prices.find(c=>c.key=='pr_counter')||CFG.prices[1]||{}).key;
  if(!k1){if(!auto)toast('Add a price column first (Product Management › Columns)',1);return 0}
  const nk=p=>(String(p.cat||p.category||'')+'|'+String(p.name||'')).trim().toLowerCase(),cnt={};L.forEach(p=>cnt[nk(p)]=(cnt[nk(p)]||0)+1);
  const have=new Set(PRODUCTS.map(p=>String(p.id).toLowerCase())),ex=PRODUCTS.map(p=>[String(p.category||'').trim().toLowerCase(),String(p.name||'').trim().toLowerCase(),+((p.prices||{})[k1])||0]),add=[];let skip=0;
  for(const p of L){const name=String(p.name||'').trim(),cat=String(p.cat||p.category||'').trim();if(!name||!cat){skip++;continue}
    const sp=p.sp==null||p.sp===''?'':+p.sp,cp=p.cp==null||p.cp===''?'':+p.cp,dn=cnt[nk(p)]>1,id=String(p.id||'P-'+Date.now().toString(36).toUpperCase()+add.length);
    if(have.has(id.toLowerCase())||ex.some(e=>e[0]==cat.toLowerCase()&&e[1]==name.toLowerCase()&&(!dn||e[2]==(+sp||0)))){skip++;continue}
    add.push({id,cat,sp,cp,no:p.no,name:dn?`${name} (Rs.${sp!==''?sp:cp})`:name})}
  if(!add.length){if(!auto)toast(`Nothing new: all ${skip} products are already there`);return 0}
  if(!auto&&!confirm(`${add.length} new products will be added${skip?` (${skip} already exist and are skipped)`:''}:\n${add.slice(0,12).map(x=>'• '+x.name).join('\n')}${add.length>12?'\n…':''}\n\nContinue?`))return;
  const NK=add.some(x=>x.no)?await ensureNoCol(add):null;for(const x of add){const o={productId:x.id,id:x.id,shop:'Book Centre',active:true,name:x.name,category:x.cat,stock:'',cost:'',prices:{},details:{},baseVersion:0,version:0};o.prices[k1]=x.sp;if(k2)o.prices[k2]=x.cp;if(x.no&&NK)o.details[NK]=String(x.no);
    await put('products',o);await put('queue',{id:'P-'+x.id,type:'product',data:o})}
  stat();syncNow();if(auto)return add.length;toast(`${add.length} products added${LOCAL()?'':'. Syncing to the sheet…'}`);adminV('products')}
/* "No." column: found by name, or created (and synced to the sheet) the first time it is needed */
async function ensureNoCol(L){if(!L.some(p=>p.no))return null;const f=()=>CFG.details.find(c=>/^no\.?$/i.test(c.label.trim()));
  if(!f()){const key=newKey('detail');await colDo('addColumn',{type:'detail',key,label:'No.'},c=>c.details.push({key,label:'No.'}),'Column "No." added')}const c=f();return c?c.key:null}
