/* ---- old data (before price columns existed) ---- */
const LEG=[['sku','SKU / barcode'],['author','Author'],['publisher','Publisher'],['size','Size'],['colour','Colour'],['notes','Notes'],['unit','Unit']];
async function migrateAll(){const P=await all('products'),Q=(await all('queue')).filter(x=>x.type=='product'),old=[...P,...Q.map(x=>x.data)].filter(p=>p&&!p.prices);if(!old.length)return;
  const c={prices:CFG.prices.map(x=>({...x})),details:CFG.details.map(x=>({...x}))},has=l=>[...c.prices,...c.details].some(x=>x.label.toLowerCase()==String(l).toLowerCase());
  old.forEach(p=>(p.extraPrices||[]).forEach(x=>{if(x.label&&!has(x.label))c.prices.push({key:newKey('price'),label:String(x.label)})}));
  LEG.forEach(([k,l])=>{if(old.some(p=>p[k]!==''&&p[k]!=null&&!(k=='unit'&&p[k]=='pcs'))&&!has(l))c.details.push({key:newKey('detail'),label:l})});
  await saveCfg(c);
  const conv=p=>{p.prices={};p.details={};const sp=(key,v)=>{if(v!==''&&v!=null&&!isNaN(+v)&&c.prices.some(x=>x.key==key))p.prices[key]=+v};sp('pr_counter',p.counterPrice);sp('pr_price',p.salesmanPrice);
    (p.extraPrices||[]).forEach(x=>{const col=c.prices.find(y=>y.label.toLowerCase()==String(x.label).toLowerCase());if(col&&x.amount!==''&&!isNaN(+x.amount))p.prices[col.key]=+x.amount});
    LEG.forEach(([k,l])=>{const col=c.details.find(y=>y.label.toLowerCase()==l.toLowerCase());if(col&&p[k]!==''&&p[k]!=null)p.details[col.key]=String(p[k])});
    ['counterPrice','salesmanPrice','extraPrices',...LEG.map(x=>x[0])].forEach(k=>delete p[k])};
  old.forEach(conv);for(const p of P)if(old.includes(p))await put('products',p);for(const x of Q)if(old.includes(x.data))await put('queue',x)}
