/* ---- sync ---- */
async function ack(res,q){for(const r of res)if(r.ok)await del('queue',r.id);else await put('queue',{...q.find(x=>x.id==r.id),error:r.error})}
async function syncNow(){if(busy||!navigator.onLine||!URLX||!TOK)return stat();busy=true;$('#sy').textContent='Syncing…';
  try{const q=await all('queue'),by=t=>q.filter(x=>x.type==t);
   if(by('bill').length)await ack((await api('syncBills',{bills:by('bill').map(x=>x.data)})).results,q);
   if(isA()){if(by('purchase').length)await ack((await api('syncPurchases',{purchases:by('purchase').map(x=>x.data)})).results,q);
    for(const x of by('product')){const j=await api('saveProduct',{product:x.data});if(j.conflict)await put('queue',{...x,error:'A newer version is on the sheet. Reopen the product.'});else{await del('queue',x.id);x.data.version=j.version;await put('products',x.data)}}
    for(const x of by('cancel')){try{await api('cancelBill',x.data);await del('queue',x.id)}catch(e){await put('queue',{...x,error:e.message})}}}
   await kset('last',new Date().toLocaleString());await stat()}catch(e){$('#sy').textContent='Sync error: '+e.message}busy=false}
